//! Runtime support for the NPC scripts generated by `tools/scripts-import/convert_npcs.py`.
#![allow(dead_code)]

use script_sdk::{Context, Function, Request, Value, Variable, VariableScope};

/// Raised by `end`/`close`: unwinds every `callsub` and `callfunc` frame and is not an error.
pub const END: &str = "\u{0}end";

pub fn n(value: i32) -> Value {
    Value::Number(value)
}

pub fn s(value: &str) -> Value {
    Value::String(value.into())
}

pub fn finish(result: Result<Value, String>) -> Result<(), String> {
    match result {
        Ok(_) => Ok(()),
        Err(error) if error == END => Ok(()),
        Err(error) => Err(error),
    }
}

pub fn op(left: Value, operator: &str, right: Value) -> Result<Value, String> {
    if let (Value::String(a), Value::String(b)) = (&left, &right) {
        let ordering = match operator {
            "<" => Some(a < b),
            ">" => Some(a > b),
            "<=" => Some(a <= b),
            ">=" => Some(a >= b),
            _ => None,
        };
        if let Some(result) = ordering {
            return Ok(Value::Number(i32::from(result)));
        }
    }
    if matches!(operator, "==" | "!=") && left.is_number() != right.is_number() {
        let equal = left.text() == right.text();
        return Ok(Value::Number(i32::from(equal == (operator == "=="))));
    }
    left.binary(operator, right)
}

pub fn eq(left: &Value, right: &Value) -> bool {
    left == right || (left.is_number() != right.is_number() && left.text() == right.text())
}

pub fn constant(ctx: &Context, name: &str) -> Result<Value, String> {
    ctx.constant(name)
}

fn scope_of(name: &str) -> (VariableScope, &str) {
    if let Some(rest) = name.strip_prefix("##") {
        (VariableScope::Account, rest)
    } else if let Some(rest) = name.strip_prefix('#') {
        (VariableScope::Account, rest)
    } else if let Some(rest) = name.strip_prefix("$@") {
        (VariableScope::ServerTemporary, rest)
    } else if let Some(rest) = name.strip_prefix('$') {
        (VariableScope::Server, rest)
    } else if let Some(rest) = name.strip_prefix('@') {
        (VariableScope::CharacterTemporary, rest)
    } else if let Some(rest) = name.strip_prefix("''").or_else(|| name.strip_prefix('\'')) {
        (VariableScope::Instance, rest)
    } else if let Some(rest) = name.strip_prefix('.') {
        (VariableScope::NpcInstance, rest)
    } else {
        (VariableScope::Character, name)
    }
}

fn coerce(name: &str, value: Value) -> Result<Value, String> {
    match (name.ends_with('$'), value) {
        (true, Value::Number(number)) => Ok(Value::String(number.to_string())),
        (false, Value::String(text)) => Ok(Value::Number(text.trim().parse().unwrap_or(0))),
        (_, value) => Ok(value),
    }
}

pub fn get(ctx: &Context, name: &str) -> Result<Value, String> {
    get_at(ctx, name, &n(0))
}

pub fn get_at(ctx: &Context, name: &str, index: &Value) -> Result<Value, String> {
    let index = u32::try_from(index.number_value()?).map_err(|_| "Negative array index")?;
    let (scope, stripped) = scope_of(name);
    if index == 0 && matches!(scope, VariableScope::Character) {
        return ctx.read(name);
    }
    ctx.request(Request::VariableRead { scope, name: stripped.into(), index })
}

pub fn set(ctx: &Context, name: &str, value: Value) -> Result<(), String> {
    set_at(ctx, name, &n(0), value)
}

pub fn set_at(ctx: &Context, name: &str, index: &Value, value: Value) -> Result<(), String> {
    let index = u32::try_from(index.number_value()?).map_err(|_| "Negative array index")?;
    let (scope, stripped) = scope_of(name);
    let value = coerce(name, value)?;
    if index == 0 && matches!(scope, VariableScope::Character | VariableScope::CharacterTemporary | VariableScope::Account | VariableScope::Server | VariableScope::ServerTemporary) {
        return ctx.write(name, value);
    }
    ctx.request(Request::VariablesWrite(vec![Variable { scope, name: stripped.into(), index, value }])).map(|_| ())
}

fn default_value(string: bool) -> Value {
    if string { s("") } else { n(0) }
}

pub fn local_get(array: &[Value], index: &Value, string: bool) -> Value {
    index.number_value().ok().and_then(|index| usize::try_from(index).ok()).and_then(|index| array.get(index).cloned()).unwrap_or_else(|| default_value(string))
}

pub fn local_set(array: &mut Vec<Value>, index: &Value, value: Value, string: bool) {
    let Some(index) = index.number_value().ok().and_then(|index| usize::try_from(index).ok()) else { return };
    if index > 65_535 {
        return;
    }
    if array.len() <= index {
        array.resize(index + 1, default_value(string));
    }
    array[index] = value;
}

pub fn arg(args: &[Value], index: i32, default: Value) -> Value {
    usize::try_from(index).ok().and_then(|index| args.get(index).cloned()).unwrap_or(default)
}

/// `select` and `menu`: the options are `:` separated, empty ones are skipped, the answer is 1-based.
pub fn select(ctx: &Context, options: &[&str]) -> Result<i32, String> {
    let options: Vec<Value> = options.iter().flat_map(|option| option.split(':')).filter(|option| !option.is_empty()).map(s).collect();
    let selected = ctx.call(Function::Select, options.clone())?.number_value()?;
    if selected < 1 || selected as usize > options.len() {
        return Err("Conversation cancelled".into());
    }
    Ok(selected)
}

pub fn select_text(ctx: &Context, options: &[Value]) -> Result<i32, String> {
    let joined = options.iter().map(Value::text).collect::<Vec<_>>().join(":");
    select(ctx, &[joined.as_str()])
}

/// `input_min_value` and `input_max_value` of rathena's script configuration, the limits of an input box without bounds.
const INPUT_MIN_NUMBER: i32 = 0;
const INPUT_MAX_NUMBER: i32 = 10_000_000;
const INPUT_MAX_TEXT: i32 = 2047;

/// `input` of a number: the entry clamped to `[min, max]` and the status (-1 below the minimum, 1 above the maximum, 0 inside).
pub fn input_number(ctx: &Context, bounds: &[i32]) -> Result<(Value, i32), String> {
    let (min, max) = (bounds.first().copied().unwrap_or(INPUT_MIN_NUMBER), bounds.get(1).copied().unwrap_or(INPUT_MAX_NUMBER));
    let entered = ctx.call(Function::InputNumber, vec![])?.number_value()?;
    Ok(match entered {
        entered if entered > max => (n(max), 1),
        entered if entered < min => (n(min), -1),
        entered => (n(entered), 0),
    })
}

/// `input` of a string: the status compares the length with the bounds like `input_number` does for the value.
pub fn input_text(ctx: &Context, bounds: &[i32]) -> Result<(Value, i32), String> {
    let (min, max) = (bounds.first().copied().unwrap_or(0), bounds.get(1).copied().unwrap_or(INPUT_MAX_TEXT));
    let entered = ctx.call(Function::InputString, vec![])?.text();
    let length = entered.chars().count() as i32;
    Ok(match length {
        length if length > max => (Value::String(entered.chars().take(max.max(0) as usize).collect()), 1),
        length if length < min => (Value::String(entered), -1),
        _ => (Value::String(entered), 0),
    })
}

pub fn strlen(value: Value) -> Result<Value, String> {
    Ok(n(value.text().chars().count() as i32))
}

pub fn substr(value: Value, start: Value, end: Value) -> Result<Value, String> {
    let text: Vec<char> = value.text().chars().collect();
    let (start, end) = (start.number_value()?, end.number_value()?);
    if start < 0 || end < start || start as usize >= text.len() {
        return Ok(s(""));
    }
    let end = (end as usize).min(text.len() - 1);
    Ok(Value::String(text[start as usize..=end].iter().collect()))
}

pub fn charat(value: Value, index: Value) -> Result<Value, String> {
    let index = index.number_value()?;
    Ok(Value::String(usize::try_from(index).ok().and_then(|index| value.text().chars().nth(index)).map(String::from).unwrap_or_default()))
}

pub fn atoi(value: Value) -> Result<Value, String> {
    Ok(n(value.text().trim().parse().unwrap_or(0)))
}

/// Case-insensitive "contains".
pub fn compare(haystack: Value, needle: Value) -> Result<Value, String> {
    Ok(n(i32::from(haystack.text().to_lowercase().contains(&needle.text().to_lowercase()))))
}

pub fn strtolower(value: Value) -> Result<Value, String> {
    Ok(Value::String(value.text().to_lowercase()))
}

pub fn strtoupper(value: Value) -> Result<Value, String> {
    Ok(Value::String(value.text().to_uppercase()))
}

/// Every entry of a stored array (`@x[]`, `$x[]`, `#x[]`, `.x[]`) up to the last one that is not zero or empty.
pub fn array_values(ctx: &Context, name: &str) -> Result<Vec<Value>, String> {
    match ctx.call(Function::ArrayGet, vec![s(name)])? {
        Value::Array(values) => Ok(values),
        _ => Err("Invalid array contents".into()),
    }
}

/// Replaces the stored array: entries past the new length are reset.
pub fn array_store(ctx: &Context, name: &str, values: Vec<Value>) -> Result<(), String> {
    ctx.call(Function::ArraySet, vec![s(name), Value::Array(values)]).map(|_| ())
}

pub fn array_size(ctx: &Context, name: &str) -> Result<Value, String> {
    Ok(n(array_values(ctx, name)?.len() as i32))
}

fn is_text(name: &str) -> bool {
    name.trim_end_matches(']').split('[').next().is_some_and(|base| base.ends_with('$'))
}

/// `deletearray name[start], count`: the entries after the deleted ones move up; without `count` everything from `start` on goes.
fn remove_range(values: &mut Vec<Value>, start: &Value, count: &[Value]) -> Result<(), String> {
    let start = usize::try_from(start.number_value()?).unwrap_or(0).min(values.len());
    let end = match count.first() {
        Some(count) => start.saturating_add(usize::try_from(count.number_value()?).unwrap_or(0)).min(values.len()),
        None => values.len(),
    };
    values.drain(start..end);
    Ok(())
}

pub fn local_delete(values: &mut Vec<Value>, start: &Value, count: &[Value]) -> Result<(), String> {
    remove_range(values, start, count)
}

pub fn array_delete(ctx: &Context, name: &str, start: &Value, count: &[Value]) -> Result<(), String> {
    let mut values = array_values(ctx, name)?;
    remove_range(&mut values, start, count)?;
    array_store(ctx, name, values)
}

/// `count` entries of `source` from `start`, missing ones read as the default of the array's type.
pub fn slice_of(source: &[Value], start: &Value, count: &Value, string: bool) -> Result<Vec<Value>, String> {
    let (start, count) = (usize::try_from(start.number_value()?).unwrap_or(0), usize::try_from(count.number_value()?).unwrap_or(0).min(65_535));
    Ok((start..start + count).map(|index| source.get(index).cloned().unwrap_or_else(|| default_value(string))).collect())
}

pub fn local_splice(target: &mut Vec<Value>, start: &Value, values: Vec<Value>, string: bool) -> Result<(), String> {
    let start = usize::try_from(start.number_value()?).unwrap_or(0);
    for (offset, value) in values.into_iter().enumerate() {
        local_set(target, &n((start + offset) as i32), value, string);
    }
    Ok(())
}

pub fn array_splice(ctx: &Context, name: &str, start: &Value, values: Vec<Value>) -> Result<(), String> {
    let string = is_text(name);
    let mut target = array_values(ctx, name)?;
    local_splice(&mut target, start, values, string)?;
    array_store(ctx, name, target)
}

pub fn array_implode(ctx: &Context, name: &str, delimiter: Value) -> Result<Value, String> {
    implode(&array_values(ctx, name)?, delimiter)
}

/// A local variable the script may name at run time through `getd` and `setd`.
pub enum LocalRef<'a> {
    Scalar(&'a Value),
    Array(&'a Vec<Value>),
}

pub enum LocalMut<'a> {
    Scalar(&'a mut Value),
    Array(&'a mut Vec<Value>),
}

/// `name[index]` as `(name, index)`, lower case like every stored variable name.
fn split_name(name: &Value) -> Result<(String, i32), String> {
    let text = name.text().to_lowercase();
    match text.split_once('[') {
        Some((base, rest)) => Ok((base.trim().to_string(), rest.trim_end_matches(']').trim().parse().map_err(|_| "Invalid array index in a variable name")?)),
        None => Ok((text.trim().to_string(), 0)),
    }
}

pub fn getd(ctx: &Context, name: &Value, locals: &[(&str, LocalRef)]) -> Result<Value, String> {
    let (base, index) = split_name(name)?;
    let written = name.text();
    if written.starts_with(|first: char| first.is_ascii_uppercase()) && written.chars().all(|c| c.is_ascii_uppercase() || c.is_ascii_digit() || c == '_') {
        if let Ok(value) = ctx.constant(&written) {
            return Ok(value);
        }
    }
    if !base.starts_with(".@") {
        return get_at(ctx, &base, &n(index));
    }
    Ok(match locals.iter().find(|(known, _)| *known == base) {
        Some((_, LocalRef::Scalar(value))) if index == 0 => (*value).clone(),
        Some((_, LocalRef::Array(values))) => local_get(values, &n(index), base.ends_with('$')),
        _ => default_value(base.ends_with('$')),
    })
}

/// `getarraysize(getd("name"))`.
pub fn getd_size(ctx: &Context, name: &Value, locals: &[(&str, LocalRef)]) -> Result<Value, String> {
    let (base, _) = split_name(name)?;
    if !base.starts_with(".@") {
        return array_size(ctx, &base);
    }
    Ok(n(match locals.iter().find(|(known, _)| *known == base) {
        Some((_, LocalRef::Array(values))) => values.len() as i32,
        Some((_, LocalRef::Scalar(value))) => i32::from(value.truthy()),
        None => 0,
    }))
}

pub fn setd(ctx: &Context, name: &Value, value: Value, locals: &mut [(&str, LocalMut)]) -> Result<(), String> {
    let (base, index) = split_name(name)?;
    if !base.starts_with(".@") {
        return set_at(ctx, &base, &n(index), value);
    }
    match locals.iter_mut().find(|(known, _)| *known == base) {
        Some((_, LocalMut::Scalar(target))) if index == 0 => **target = value,
        Some((_, LocalMut::Array(values))) => local_set(values, &n(index), value, base.ends_with('$')),
        _ => return Err(format!("setd cannot reach the local variable {base}")),
    }
    Ok(())
}

/// `strpos(text, search{, start})`: index of the first match, -1 when there is none.
pub fn strpos(text: Value, search: Value, start: &[Value]) -> Result<Value, String> {
    let (text, search) = (text.text(), search.text());
    let start = start.first().map_or(Ok(0), Value::number_value)?.max(0) as usize;
    let characters: Vec<char> = text.chars().collect();
    let needle: Vec<char> = search.chars().collect();
    Ok(n((start..=characters.len().saturating_sub(needle.len())).find(|position| characters.get(*position..*position + needle.len()) == Some(needle.as_slice())).map_or(-1, |position| position as i32)))
}

/// `charisalpha(text, index)`.
pub fn charisalpha(text: Value, index: Value) -> Result<Value, String> {
    Ok(n(i32::from(usize::try_from(index.number_value()?).ok().and_then(|index| text.text().chars().nth(index)).is_some_and(char::is_alphabetic))))
}

/// `insertchar(text, character, index)`: a negative index counts from the end.
pub fn insertchar(text: Value, character: Value, index: Value) -> Result<Value, String> {
    let characters: Vec<char> = text.text().chars().collect();
    let index = index.number_value()?;
    let position = if index < 0 { characters.len().saturating_sub(index.unsigned_abs() as usize) } else { (index as usize).min(characters.len()) };
    let mut result: String = characters[..position].iter().collect();
    result.push_str(&character.text().chars().take(1).collect::<String>());
    result.extend(&characters[position..]);
    Ok(Value::String(result))
}

/// `getpartymember`: fills `$@partymembername$`, `$@partymembercid` or `$@partymemberaid` and `$@partymembercount`.
pub fn party_members(ctx: &Context, party: Value, kind: Value) -> Result<(), String> {
    let kind_number = kind.number_value()?;
    let Value::Array(members) = ctx.call(Function::GetPartyMember, vec![party, kind])? else {
        return Err("Invalid party member list".into());
    };
    let array = match kind_number {
        1 => "$@partymembercid",
        2 => "$@partymemberaid",
        _ => "$@partymembername$",
    };
    set(ctx, "$@partymembercount", n(members.len() as i32))?;
    for (index, member) in members.into_iter().enumerate() {
        set_at(ctx, array, &n(index as i32), member)?;
    }
    Ok(())
}

/// `sprintf` with `%d`, `%i`, `%s` and `%%`, honouring the `-`, `0` flags and a width.
pub fn sprintf(format: Value, arguments: Vec<Value>) -> Result<Value, String> {
    let format = format.text();
    let mut remaining = arguments.into_iter();
    let mut output = String::new();
    let mut characters = format.chars().peekable();
    while let Some(character) = characters.next() {
        if character != '%' {
            output.push(character);
            continue;
        }
        let (mut left, mut zero, mut width) = (false, false, 0usize);
        while let Some(&flag) = characters.peek() {
            match flag {
                '-' => left = true,
                '0' => zero = true,
                _ => break,
            }
            characters.next();
        }
        while let Some(digit) = characters.peek().and_then(|digit| digit.to_digit(10)) {
            width = width * 10 + digit as usize;
            characters.next();
        }
        let text = match characters.next() {
            Some('%') => {
                output.push('%');
                continue;
            }
            Some('d' | 'i') => remaining.next().map(|value| value.number_value()).transpose()?.unwrap_or(0).to_string(),
            Some('s') => remaining.next().map(|value| value.text()).unwrap_or_default(),
            _ => return Err("Unsupported sprintf format".into()),
        };
        let padding = width.saturating_sub(text.chars().count());
        match (left, zero) {
            (true, _) => output.extend([text.as_str(), &" ".repeat(padding)]),
            (false, true) => output.extend([&"0".repeat(padding), text.as_str()]),
            (false, false) => output.extend([&" ".repeat(padding), text.as_str()]),
        }
    }
    Ok(Value::String(output))
}

pub fn implode(array: &[Value], delimiter: Value) -> Result<Value, String> {
    Ok(Value::String(array.iter().map(Value::text).collect::<Vec<_>>().join(&delimiter.text())))
}

pub fn explode(value: Value, delimiter: Value) -> Result<Vec<Value>, String> {
    let (text, delimiter) = (value.text(), delimiter.text());
    if delimiter.is_empty() {
        return Ok(vec![Value::String(text)]);
    }
    Ok(text.split(delimiter.as_str()).map(s).collect())
}

pub fn countstr(value: Value, needle: Value) -> Result<Value, String> {
    let needle = needle.text();
    Ok(n(if needle.is_empty() { 0 } else { value.text().matches(needle.as_str()).count() as i32 }))
}

pub fn replacestr(value: Value, search: Value, replacement: Value, options: &[Value]) -> Result<Value, String> {
    let (text, search, replacement) = (value.text(), search.text(), replacement.text());
    let case_sensitive = options.first().map_or(Ok(1), Value::number_value)? != 0;
    let limit = options.get(1).map_or(Ok(-1), Value::number_value)?;
    if search.is_empty() {
        return Ok(Value::String(text));
    }
    let (haystack, needle) = if case_sensitive { (text.clone(), search.clone()) } else { (text.to_ascii_lowercase(), search.to_ascii_lowercase()) };
    let mut result = String::new();
    let (mut cursor, mut replaced) = (0, 0);
    while limit < 0 || replaced < limit {
        let Some(found) = haystack[cursor..].find(&needle) else { break };
        result.push_str(&text[cursor..cursor + found]);
        result.push_str(&replacement);
        cursor += found + needle.len();
        replaced += 1;
    }
    result.push_str(&text[cursor..]);
    Ok(Value::String(result))
}

pub fn delchar(value: Value, characters: Value) -> Result<Value, String> {
    let removed = characters.text();
    Ok(Value::String(value.text().chars().filter(|character| !removed.contains(*character)).collect()))
}

/// `npcskill`: the NPC casts a support skill on the attached player with its own level and intelligence.
pub fn npc_skill(ctx: &Context, skill: Value, level: Value, stat: Value, npc_level: Value) -> Result<(), String> {
    let (level, stat, npc_level) = (level.number_value()?, stat.number_value()?, npc_level.number_value()?);
    match skill.text().to_ascii_uppercase().as_str() {
        "AL_HEAL" => {
            let hp = (npc_level + stat) / 8 * (4 + 8 * level);
            ctx.call(Function::Heal, vec![n(hp), n(0)])?;
        }
        buff @ ("AL_BLESSING" | "AL_INCAGI") => {
            let status = if buff == "AL_BLESSING" { "SC_BLESSING" } else { "SC_INCREASEAGI" };
            ctx.call(Function::StartStatus, vec![ctx.constant(status)?, n(40_000 + 20_000 * level), n(level)])?;
        }
        other => return Err(format!("npcskill does not support {other}")),
    }
    Ok(())
}

/// `getinventorylist`: fills the `@inventorylist_*` arrays from the host's flat rows.
pub fn inventory_list(ctx: &Context) -> Result<(), String> {
    const COLUMNS: [&str; 10] = ["id", "amount", "equip", "refine", "identify", "attribute", "card1", "card2", "card3", "card4"];
    let Value::Array(rows) = ctx.call(Function::GetInventoryList, vec![])? else { return Err("Invalid inventory list".into()) };
    for (column, name) in COLUMNS.iter().enumerate() {
        array_store(ctx, &format!("@inventorylist_{name}"), rows.chunks(COLUMNS.len()).map(|row| row[column].clone()).collect())?;
    }
    set(ctx, "@inventorylist_count", n((rows.len() / COLUMNS.len()) as i32))
}

/// `sscanf` with `%s` and `%d`; scanning stops at the first mismatch and only the values found are returned.
pub fn sscanf(input: Value, format: Value) -> Vec<Value> {
    let (input, format) = (input.text(), format.text());
    let (mut text, mut pattern) = (input.chars().peekable(), format.chars());
    let mut found = Vec::new();
    while let Some(expected) = pattern.next() {
        if expected == '%' {
            while text.next_if(|c| c.is_whitespace()).is_some() {}
            match pattern.next() {
                Some('s') => {
                    let mut word = String::new();
                    while let Some(c) = text.next_if(|c| !c.is_whitespace()) {
                        word.push(c);
                    }
                    if word.is_empty() {
                        break;
                    }
                    found.push(Value::String(word));
                }
                Some('d') => {
                    let mut digits = String::new();
                    if let Some(sign) = text.next_if(|c| *c == '-' || *c == '+') {
                        digits.push(sign);
                    }
                    while let Some(c) = text.next_if(char::is_ascii_digit) {
                        digits.push(c);
                    }
                    match digits.parse::<i32>() {
                        Ok(number) => found.push(Value::Number(number)),
                        Err(_) => break,
                    }
                }
                _ => break,
            }
        } else if expected.is_whitespace() {
            while text.next_if(|c| c.is_whitespace()).is_some() {}
        } else if text.next() != Some(expected) {
            break;
        }
    }
    found
}
